   411	export async function rewriteInbox(keepEventIds: Set<string>): Promise<void> {
   412		const path = inboxNotesPath();
   413		if (!existsSync(path)) return;
   414		await ensureInboxDir();
   415		const text = await readFile(path, "utf8");
   416		const entries = parseInboxText(text);
   417		const kept = entries.filter((e) => keepEventIds.has(e.event_id));
   418		const body = kept.map((e) => e.raw).join("");
   419		const tmp = `${path}.tmp.${randomBytes(6).toString("hex")}`;
