   626	/**
   627	 * Return relative paths of ALL .md files under the given roots, lexicographically sorted.
   628	 * No content is read — callers use this as a compact file index for deduplication checks.
   629	 * Significantly cheaper than readMemoryTree since it performs no file I/O beyond directory listing.
   630	 */
   631	export async function listAllMemoryFiles(
   632		roots: string[] = ["profile", "project", "tools"],
   633	): Promise<string[]> {
   634		const base = memoryDir();
   635		const abs = await collectMdFiles(base, roots);
   636		return abs.map((p) => relative(base, p));
   637	}
   638	
   639	async function collectMdFiles(base: string, roots: string[]): Promise<string[]> {
   640		const seen = new Set<string>();
   641		const out: string[] = [];
   642		for (const root of roots) {
   643			const abs = isAbsolute(root) ? resolve(root) : resolve(base, root);
   644			// Refuse path escape outside memoryDir() — security boundary.
   645			const relToBase = relative(base, abs);
   646			if (relToBase.startsWith("..") || isAbsolute(relToBase)) {
   647				console.error(`[dream-memory] refusing path outside memoryDir: ${root}`);
   648				continue;
   649			}
   650			if (!existsSync(abs)) continue;
   651			const st = await stat(abs);
   652			if (st.isFile()) {
   653				if (abs.endsWith(".md") && !seen.has(abs)) {
   654					seen.add(abs);
   655					out.push(abs);
   656				}
   657			} else if (st.isDirectory()) {
   658				await walkMd(abs, seen, out);
   659			}
   660		}
   661		// Stable order: lexicographic relative path.
   662		out.sort((a, b) => relative(base, a).localeCompare(relative(base, b)));
   663		return out;
   664	}
   665	
   666	async function walkMd(dir: string, seen: Set<string>, out: string[]): Promise<void> {
   667		for (const ent of await readdir(dir, { withFileTypes: true })) {
   668			const p = join(dir, ent.name);
   669			if (ent.isDirectory()) {
   670				await walkMd(p, seen, out);
   671			} else if (ent.isFile() && ent.name.endsWith(".md") && !seen.has(p)) {
   672				seen.add(p);
   673				out.push(p);
   674			}
   675		}
   676	}
