   786	/** Strip `qmd://<collection>/` prefix; return relative path or the input. */
   787	function qmdUriToRel(file: string | undefined): string | undefined {
   788		if (!file) return undefined;
   789		const m = /^qmd:\/\/[^/]+\/(.*)$/.exec(file);
