   799	/** Map a QMD row → our SearchHit shape. */
   800	export function qmdRowToHit(row: QmdQueryRow): SearchHit {
   801		const rel = qmdUriToRel(row.file) ?? "";
   802		const snippet = snippetText(row.snippet);
   803		const hit: SearchHit = {
   804			title: row.title ?? rel,
   805			permalink: rel.replace(/\.md$/, ""),
   806		};
   807		if (typeof row.score === "number") hit.score = row.score;
   808		if (snippet) hit.matched_chunk = snippet;
   809		if (snippet) hit.content = snippet;
   810		if (rel) hit.file_path = rel;
   811		if (row.docid) hit.docid = row.docid;
   812		return hit;
   813	}
