   905	 * Default char cap for queries shipped to qmd /query and TEI /rerank.
   906	 * Cross-encoder rerankers and bi-encoder embed models both have a 512-token
   907	 * hard limit; 1024 chars (~256 tokens) leaves comfortable headroom. Override
   908	 * via `DREAM_QUERY_MAX_CHARS` for experiments.
   909	 */
   910	export const DEFAULT_QUERY_MAX_CHARS = 1024;
   911	const DEFAULT_RERANK_TIMEOUT_MS = 15_000;
   912	const MIN_RERANK_TIMEOUT_MS = 250;
   913	const MAX_RERANK_TIMEOUT_MS = 15_000;
   914	const DEFAULT_RERANK_CANDIDATES = 60;
   915	const MAX_RERANK_CANDIDATES = 100;
   916	const DEFAULT_HYBRID_LEX_CANDIDATES = 80;
   917	const DEFAULT_HYBRID_VEC_CANDIDATES = 80;
