   921	export function normaliseQmdQuery(query: string, maxChars?: number): string {
   922		const envCap = Number(process.env.DREAM_QUERY_MAX_CHARS ?? "");
   923		const cap = maxChars ?? (Number.isFinite(envCap) && envCap > 0 ? envCap : DEFAULT_QUERY_MAX_CHARS);
   924		const cleaned = query
   925			.replace(/-/g, " ")
   926			.replace(/["']/g, " ")
   927			.replace(/[{}[\]():,|`<>;\\]/g, " ")
   928			.replace(/[\u0000-\u001f\u007f]+/g, " ")
   929			.replace(/\s+/g, " ")
   930			.trim();
   931		return cleaned.length > cap ? cleaned.slice(0, cap) : cleaned;
   932	}
