   934	function boundedInt(raw: string | undefined, fallback: number, min: number, max: number): number {
   935		if (raw === undefined) return fallback;
   936		const n = Number(raw);
   937		if (!Number.isFinite(n)) return fallback;
   938		return Math.min(max, Math.max(min, Math.floor(n)));
   939	}
