   945	async function fetchWithTimeout(url: string, init: RequestInit, timeoutMs: number): Promise<Response> {
   946		const ctrl = new AbortController();
   947		if (timeoutMs <= 0) ctrl.abort();
   948		const timer = timeoutMs > 0 ? setTimeout(() => ctrl.abort(), timeoutMs) : undefined;
   949		try {
   950			return await fetch(url, { ...init, signal: ctrl.signal });
   951		} finally {
   952			if (timer) clearTimeout(timer);
   953		}
   954	}
