   960	// ---------------------------------------------------------------------------
   961	// External reranker (TEI / HuggingFace text-embeddings-inference).
   962	//
   963	// qmd's built-in `node-llama-cpp` reranker leaks Metal-backed IOSurface memory
   964	// on Apple Silicon (see `~/.pi/agent/memory/profile/qmd-mcp-memory-leak.md`).
   965	// When DREAM_RERANK_PROVIDER=tei is set, we POST {query, texts} to TEI's
   966	// /rerank endpoint, then sort by TEI score and slice to pageSize. Active
   967	// recall's hybrid HTTP path keeps qmd on lex-only candidates and gets vec
   968	// candidates from qmd-vector-sidecar, so qmd's RSS-heavy vec branch is not on
   969	// the hot path.
   970	//
   971	// TEI lives in its own process (Rust/Candle), so allocator pressure does not
   972	// touch qmd's Node heap. See `docs/reranking-decision.md`.
   973	// ---------------------------------------------------------------------------
   974	
   975	/** Resolved rerank-provider config; null when external rerank is disabled. */
   976	function resolveRerankProvider(): {
   977		url: string;
   978		timeoutMs: number;
   979		candidates: number;
   980	} | null {
   981		const provider = process.env.DREAM_RERANK_PROVIDER;
   982		if (!provider || provider === "qmd" || provider === "none") return null;
   983		if (provider !== "tei") return null; // future: other providers
   984		const url = process.env.DREAM_RERANK_URL ?? "http://127.0.0.1:8182/rerank";
   985		const timeoutMs = boundedInt(
   986			process.env.DREAM_RERANK_TIMEOUT_MS,
   987			DEFAULT_RERANK_TIMEOUT_MS,
   988			MIN_RERANK_TIMEOUT_MS,
   989			MAX_RERANK_TIMEOUT_MS,
   990		);
   991		const candidates = boundedInt(
   992			process.env.DREAM_RERANK_CANDIDATES,
   993			DEFAULT_RERANK_CANDIDATES,
   994			1,
   995			MAX_RERANK_CANDIDATES,
   996		);
   997		return { url, timeoutMs, candidates };
   998	}
