  1000	/**
  1001	 * Re-score `texts` against `query` via a TEI-shaped /rerank endpoint.
  1002	 * Returns the indices sorted by descending relevance, with scores attached.
  1003	 * Empty array on any failure — caller falls back to the pre-rerank order.
  1004	 *
  1005	 * TEI response shape (text-embeddings-router v1.x):
  1006	 *   [{ index: number, score: number, text?: string }, ...] // already sorted desc
  1007	 */
  1008	export async function rerankViaTei(
  1009		query: string,
  1010		texts: string[],
  1011		opts: { url: string; timeoutMs: number; label?: string },
  1012	): Promise<{ index: number; score: number }[]> {
  1013		if (texts.length === 0) return [];
  1014		if (opts.timeoutMs <= 0) {
  1015			logRerankDiagnostic(opts.label, "search budget exhausted");
  1016			return [];
  1017		}
  1018		try {
  1019			const resp = await fetchWithTimeout(opts.url, {
  1020				method: "POST",
  1021				headers: { "Content-Type": "application/json" },
  1022				body: JSON.stringify({ query, texts, raw_scores: false }),
  1023			}, opts.timeoutMs);
  1024			if (!resp.ok) {
  1025				logRerankDiagnostic(opts.label, `HTTP ${resp.status}`);
  1026				return [];
  1027			}
  1028			const data = (await resp.json()) as Array<{ index: number; score: number }>;
  1029			if (!Array.isArray(data)) {
  1030				logRerankDiagnostic(opts.label, "invalid response shape");
  1031				return [];
  1032			}
  1033			return data
  1034				.filter((d) => typeof d.index === "number" && typeof d.score === "number")
  1035				.sort((a, b) => b.score - a.score);
  1036		} catch (err) {
  1037			const e = err as Error;
  1038			const reason = e.name === "AbortError" ? `timeout after ${opts.timeoutMs}ms` : e.message;
  1039			logRerankDiagnostic(opts.label, reason);
  1040			return [];
  1041		}
  1042	}
