  1094	/** Map a sidecar /search hit row → our SearchHit shape. */
  1095	function sidecarRowToHit(row: {
  1096		chunk_id?: string;
  1097		source_doc_id?: string;
  1098		path?: string;
  1099		title?: string | null;
  1100		content?: string;
  1101		score?: number;
  1102		distance?: number;
  1103	}): SearchHit {
  1104		const path = row.path ?? row.source_doc_id ?? "";
  1105		const hit: SearchHit = {
  1106			title: row.title ?? path,
  1107			permalink: path.replace(/\.md$/, ""),
  1108		};
  1109		if (typeof row.score === "number") hit.score = row.score;
  1110		else if (typeof row.distance === "number") hit.score = Math.max(0, 1 - row.distance / 2);
  1111		if (row.content) {
  1112			hit.content = row.content;
  1113			hit.matched_chunk = row.content;
  1114		}
  1115		if (path) hit.file_path = path;
  1116		if (row.chunk_id) hit.docid = row.chunk_id;
  1117		return hit;
  1118	}
  1119	
  1120	function searchHitRerankText(hit: SearchHit): string {
  1121		return hit.matched_chunk ?? hit.content ?? hit.title ?? "";
  1122	}
  1123	
  1124	function normaliseSearchPath(path: string | undefined): string {
  1125		return (path ?? "")
  1126			.replace(/\.md$/, "")
  1127			.replace(/^(dream-memory|memory)\//, "");
  1128	}
  1129	
  1130	function searchHitKey(hit: SearchHit): string {
  1131		return normaliseSearchPath(hit.permalink) ||
  1132			normaliseSearchPath(hit.file_path) ||
  1133			hit.title;
  1134	}
  1135	
  1136	function mergeSearchHits(groups: SearchHit[][]): SearchHit[] {
  1137		const best = new Map<string, SearchHit>();
  1138		for (const group of groups) {
  1139			for (const hit of group) {
  1140				const key = searchHitKey(hit);
  1141				const prev = best.get(key);
  1142				if (!prev || (hit.score ?? 0) > (prev.score ?? 0)) best.set(key, hit);
  1143			}
  1144		}
  1145		return [...best.values()];
  1146	}
  1147	
  1148	function reciprocalRankFuse(groups: SearchHit[][], limit: number): SearchHit[] {
  1149		const k = 60;
  1150		const fused = new Map<string, { hit: SearchHit; score: number; bestRank: number }>();
  1151		for (const group of groups) {
  1152			group.forEach((hit, index) => {
  1153				const key = searchHitKey(hit);
  1154				const rank = index + 1;
  1155				const score = 1 / (k + rank);
  1156				const prev = fused.get(key);
  1157				if (!prev) {
  1158					fused.set(key, { hit, score, bestRank: rank });
  1159					return;
  1160				}
  1161				prev.score += score;
  1162				if ((hit.score ?? 0) > (prev.hit.score ?? 0)) prev.hit = hit;
  1163				prev.bestRank = Math.min(prev.bestRank, rank);
  1164			});
  1165		}
  1166		return [...fused.values()]
  1167			.sort((a, b) => (b.score - a.score) || (a.bestRank - b.bestRank))
  1168			.slice(0, limit)
  1169			.map(({ hit, score }) => ({ ...hit, score }));
  1170	}
