  1172	type RerankProviderConfig = NonNullable<ReturnType<typeof resolveRerankProvider>>;
  1173	
  1174	async function rerankSearchHitsViaTei(
  1175		query: string,
  1176		hits: SearchHit[],
  1177		pageSize: number,
  1178		teiCfg: RerankProviderConfig,
  1179		deadlineMs: number,
  1180		label: string,
  1181	): Promise<SearchHit[] | null> {
  1182		const candidates = hits.slice(0, teiCfg.candidates);
  1183		const texts = candidates.map(searchHitRerankText);
  1184		const rerankTimeoutMs = Math.min(teiCfg.timeoutMs, remainingBudgetMs(deadlineMs));
  1185		// Silent skip when retrieval consumed the budget — TEI needs ≥ MIN_RERANK_TIMEOUT_MS
  1186		// to be worth attempting. Caller falls through to the fused/vec order. No warn.
  1187		if (rerankTimeoutMs < MIN_RERANK_TIMEOUT_MS) return null;
  1188		const ranked = await rerankViaTei(normaliseQmdQuery(query), texts, {
  1189			url: teiCfg.url,
  1190			timeoutMs: rerankTimeoutMs,
  1191			label,
  1192		});
  1193		if (ranked.length === 0) return null;
  1194		const reordered: SearchHit[] = [];
  1195		for (const r of ranked) {
  1196			const hit = candidates[r.index];
  1197			if (!hit) continue;
  1198			reordered.push({ ...hit, score: r.score });
  1199		}
  1200		return reordered.slice(0, pageSize);
  1201	}
