  1203	/**
  1204	 * Search via the qmd-vector-sidecar HTTP service. Pure vec retrieval; an
  1205	 * optional TEI rerank step reorders the top-K to keep the comparison vs
  1206	 * the qmd path fair (qmd also reranks via TEI).
  1207	 *
  1208	 * Errors return `{ results: [], timedOut, error }` — same shape as
  1209	 * `searchMemoryHttp`, so the served arm degrades gracefully.
  1210	 */
  1211	export async function searchVectorSidecar(
  1212		query: string,
  1213		opts: SearchOptions = {},
  1214	): Promise<SearchResult> {
  1215		const url = vectorSidecarUrl();
  1216		const pageSize = opts.pageSize ?? 5;
  1217		const timeoutMs = opts.timeoutMs ?? DEFAULT_SEARCH_TIMEOUT_MS;
  1218		const deadlineMs = Date.now() + timeoutMs;
  1219		const rerank = opts.rerank !== false && process.env.RECALL_RERANK !== "0";
  1220		const teiCfg = rerank ? resolveRerankProvider() : null;
  1221		const k = teiCfg ? Math.max(pageSize, teiCfg.candidates) : pageSize;
  1222		try {
  1223			const resp = await fetchWithTimeout(url, {
  1224				method: "POST",
  1225				headers: { "Content-Type": "application/json" },
  1226				body: JSON.stringify({ query, k }),
  1227			}, timeoutMs);
  1228			if (!resp.ok) {
  1229				return { results: [], timedOut: false, error: `sidecar: HTTP ${resp.status}` };
  1230			}
  1231			const data = (await resp.json()) as { hits?: Array<Parameters<typeof sidecarRowToHit>[0]> };
  1232			const hits = data.hits ?? [];
  1233			if (teiCfg && hits.length > 1) {
  1234				const reranked = await rerankSearchHitsViaTei(
  1235					query,
  1236					hits.map(sidecarRowToHit),
  1237					pageSize,
  1238					teiCfg,
  1239					deadlineMs,
  1240					"sidecar",
  1241				);
  1242				if (reranked) {
  1243					return { results: reranked, timedOut: false };
  1244				}
  1245				// TEI rerank failed — fall through to raw vec order.
  1246			}
  1247			return { results: hits.slice(0, pageSize).map(sidecarRowToHit), timedOut: false };
  1248		} catch (err) {
  1249			const isAbort = (err as Error).name === "AbortError";
  1250			if (isAbort) return { results: [], timedOut: true };
  1251			return { results: [], timedOut: false, error: `sidecar: ${(err as Error).message}` };
  1252		}
  1253	}
