  1255	/**
  1256	 * Human-readable key for the JSONL `top5_paths` field. Keeps the original
  1257	 * path/permalink shape so an operator scanning the log can tell which file
  1258	 * each arm returned.
  1259	 */
  1260	function top5Key(h: SearchHit): string {
  1261		return h.permalink || h.file_path || h.title || "";
  1262	}
  1263	
  1264	/**
  1265	 * Cross-arm canonical match key for overlap@5 / rank-correlation math.
  1266	 *
  1267	 * qmd produces collection-relative permalinks (`project/my-pi/boot-profile`).
  1268	 * The vector sidecar produces corpus-relative paths (`memory/project/my-pi/
  1269	 * boot-profile`). They never string-equal even when both arms return the same
  1270	 * file. Reducing to the file basename (no extension) gives a stable cross-arm
  1271	 * key. Trades collision risk (two files sharing a name in different dirs) for
  1272	 * cross-arm comparability. Acceptable for dream-memory/pi-memory corpora
  1273	 * where filenames are largely unique.
  1274	 */
  1275	function top5MatchKey(h: SearchHit): string {
  1276		const raw = h.file_path || h.permalink || h.title || "";
  1277		const base = raw.split("/").pop() ?? raw;
  1278		return base.replace(/\.md$/, "");
  1279	}
  1280	
  1281	function overlapAt5(a: SearchHit[], b: SearchHit[]): number {
  1282		if (a.length === 0 && b.length === 0) return 1;
  1283		if (a.length === 0 || b.length === 0) return 0;
  1284		const sa = new Set(a.slice(0, 5).map(top5MatchKey));
  1285		let hit = 0;
  1286		for (const x of b.slice(0, 5)) if (sa.has(top5MatchKey(x))) hit++;
  1287		return hit / 5;
  1288	}
  1289	
  1290	function rankCorrelation(served: SearchHit[], shadow: SearchHit[]): number | null {
  1291		// Spearman over the intersection of canonical basenames. Returns null when
  1292		// the intersection is too small for a meaningful rank.
  1293		const aRank = new Map<string, number>();
  1294		served.forEach((h, i) => aRank.set(top5MatchKey(h), i));
  1295		const pairs: Array<[number, number]> = [];
  1296		shadow.forEach((h, i) => {
  1297			const r = aRank.get(top5MatchKey(h));
  1298			if (r !== undefined) pairs.push([r, i]);
  1299		});
  1300		if (pairs.length < 3) return null;
  1301		const n = pairs.length;
  1302		let dSum = 0;
  1303		for (const [a, b] of pairs) dSum += (a - b) ** 2;
  1304		return 1 - (6 * dSum) / (n * (n * n - 1));
  1305	}
  1306	
  1307	function shortQueryHash(query: string): string {
  1308		return createHash("sha256").update(query).digest("hex").slice(0, 12);
  1309	}
