  1381	/**
  1382	 * Search via the qmd HTTP daemon. Much faster than spawning a subprocess.
  1383	 * Activated when `DREAM_QMD_HTTP_PORT` is set or opts.httpPort is passed.
  1384	 * Connection failures return an error result; callers choose any fallback.
  1385	 *
  1386	 * Direct daemon calls default to qmd's lex+vec shape for back-compat. Active
  1387	 * recall sets `includeVec:false` for qmd_mode="search", and qmd_mode="query"
  1388	 * routes through `searchMemoryHybridHttp` instead of qmd's internal vec branch.
  1389	 */
  1390	export async function searchMemoryHttp(
  1391		query: string,
  1392		opts: {
  1393			port: number;
  1394			collection?: string;
  1395			collections?: string[];
  1396			pageSize?: number;
  1397			timeoutMs?: number;
  1398			/**
  1399			 * Include vec (semantic) embedding search alongside lex. Default: true.
  1400			 * The daemon keeps the embedding model in memory after first load
  1401			 * (~2s cold, then ~2s per unique query; repeated queries cached ~37ms).
  1402			 * Set false for strict latency budgets.
  1403			 */
  1404			includeVec?: boolean;
  1405			/**
  1406			 * Re-score merged lex+vec hits with a cross-encoder for higher precision.
  1407			 * Default: true. Warm cost ~270ms (model stays in daemon memory).
  1408			 * Improves relevance ordering and reduces noise injected into context,
  1409			 * saving tokens in the active-recall haiku call.
  1410			 */
  1411			rerank?: boolean;
  1412			candidateLimit?: number;
  1413			extraQueries?: string[];
  1414		},
  1415	): Promise<SearchResult> {
  1416		// Two-pass: when extraQueries is set, run the main query plus each sub-query
  1417		// in parallel and merge by permalink (highest score wins). Generic mechanism
  1418		// for multi-topic prompts; caller decides decomposition.
  1419		if (opts.extraQueries && opts.extraQueries.length > 0) {
  1420			const { extraQueries, ...base } = opts;
  1421			const all = await Promise.all(
  1422				[query, ...extraQueries].map((q) => searchMemoryHttp(q, base)),
  1423			);
  1424			const best = new Map<string, SearchHit>();
  1425			let anyTimedOut = false;
  1426			for (const r of all) {
  1427				if (r.timedOut) anyTimedOut = true;
  1428				for (const h of r.results) {
  1429					const key = h.permalink ?? `${h.title}${h.file_path ?? ""}`;
  1430					const prev = best.get(key);
  1431					if (!prev || (h.score ?? 0) > (prev.score ?? 0)) best.set(key, h);
  1432				}
  1433			}
  1434			const merged = [...best.values()].sort((a, b) => (b.score ?? 0) - (a.score ?? 0));
  1435			return { results: merged.slice(0, opts.pageSize ?? 5), timedOut: anyTimedOut };
  1436		}
  1437		// Federate across multiple collections when `collections` is set.
  1438		// Falls back to single-collection mode for back-compat.
  1439		const collections = opts.collections && opts.collections.length > 0
  1440			? opts.collections
  1441			: [opts.collection ?? process.env.DREAM_QMD_COLLECTION ?? DEFAULT_QMD_COLLECTION];
  1442		const n = opts.pageSize ?? 5;
  1443		const timeoutMs = opts.timeoutMs ?? 4000;
  1444		const deadlineMs = Date.now() + timeoutMs;
  1445		const includeVec = opts.includeVec ?? true;
  1446		const rerank = opts.rerank ?? true;
  1447		// External rerank provider (TEI). When enabled and rerank requested, we
  1448		// fetch a wider candidate pool from qmd with rerank disabled, then re-score
  1449		// out-of-process. Falls through to the qmd-internal rerank path otherwise.
  1450		const teiCfg = rerank ? resolveRerankProvider() : null;
  1451		const qmdRerank = teiCfg ? false : rerank;
  1452		const qmdLimit = teiCfg ? Math.max(n, teiCfg.candidates) : n;
  1453		// Sanitize query for qmd daemon: hyphens can be parsed as DSL negation, and
  1454		// raw newlines/control chars make current /query return HTTP 500. Collapsing
  1455		// to one line is semantically equivalent for BM25/vec search and keeps
  1456		// active-memory prior context safe.
  1457		const safeQuery = normaliseQmdQuery(query);
  1458		const searches: { type: string; query: string }[] = [{ type: "lex", query: safeQuery }];
  1459		if (includeVec) searches.push({ type: "vec", query: safeQuery });
  1460		try {
  1461			const resp = await fetchWithTimeout(`http://localhost:${opts.port}/query`, {
  1462				method: "POST",
  1463				headers: { "Content-Type": "application/json" },
  1464				body: JSON.stringify({
  1465					searches,
  1466					collections,
  1467					limit: qmdLimit,
  1468					rerank: qmdRerank,
  1469				}),
  1470			}, timeoutMs);
  1471			if (!resp.ok) {
  1472				// If reranking was requested and failed, retry without it.
  1473				// The reranker can fail for several reasons (model not loaded, hyphenated
  1474				// terms parsed as DSL operators, collection not fully indexed). Falling
  1475				// back to unranked lex+vec results is far better than returning nothing.
  1476				if (rerank) {
  1477					const fallbackResp = await fetchWithTimeout(`http://localhost:${opts.port}/query`, {
  1478						method: "POST",
  1479						headers: { "Content-Type": "application/json" },
  1480						body: JSON.stringify({
  1481							searches,
  1482							collections,
  1483							limit: n,
  1484							rerank: false,
  1485						}),
  1486					}, remainingBudgetMs(deadlineMs));
  1487					if (fallbackResp.ok) {
  1488						const data = await fallbackResp.json() as { results?: Record<string, unknown>[] };
  1489						return { results: (data.results ?? []).map(httpRowToHit), timedOut: false };
